WITH facts("id", "sourceId", "content") AS (VALUES
('kr_anpr_residenza_1', 'ks_anpr_residenza', 'Il servizio ANPR copre il cambio di residenza tra comuni, nello stesso comune e il rimpatrio AIRE. Gli altri casi indicati nella guida richiedono lo sportello comunale. I maggiorenni coinvolti devono convalidare. La guida descrive indirizzo, titolo di occupazione, eventuali allegati e riepilogo.'),
('kr_anpr_certificati_1', 'ks_anpr_certificati', 'La guida ANPR consente certificati per sé o un componente vivente della famiglia anagrafica. Terzi, tutori e certificati storici richiedono il comune. La richiesta prevede scelta del certificato, tipo, eventuale lingua, modalità di ricezione, anteprima e scaricamento.'),
('kr_inps_isee_1', 'ks_inps_isee', 'Per ottenere ISEE occorre presentare DSU. Il nucleo è quello alla data della DSU; redditi e patrimonio sono riferiti al secondo anno solare precedente. La DSU precompilata contiene dati autodichiarati e precompilati. I componenti maggiorenni autorizzano la precompilazione o il dichiarante fornisce gli elementi di riscontro.'))
SELECT "id", "sourceId", 1, "content", encode(sha256(convert_to("content", 'UTF8')), 'hex'), 'PENDING_REVIEW' FROM facts
ON CONFLICT ("id") DO NOTHING;

