INSERT INTO "ProcedureDefinition" ("id", "slug", "title", "description", "category", "audience", "scope", "authority", "status") VALUES
('pd_residenza', 'cambio-residenza', 'Cambio di residenza', 'Prepara la dichiarazione di residenza per il Comune competente.', 'Anagrafe', 'Persone e famiglie che cambiano residenza.', 'Nazionale, con verifiche comunali', 'Comune di destinazione', 'DRAFT'),
('pd_certificati', 'certificati-anagrafici', 'Certificati anagrafici', 'Prepara la richiesta di un certificato tramite ANPR.', 'Anagrafe', 'Persone residenti in Italia o iscritte AIRE, secondo il certificato.', 'Nazionale', 'Ministero dell’Interno e Comune competente', 'DRAFT'),
