INSERT INTO "ProcedureVersion" ("id", "procedureId", "version", "definition", "status") VALUES
('pv_residenza_1', 'pd_residenza', 1, '{"questions":[{"id":"tipo_trasferimento","title":"Quale trasferimento devi dichiarare?","type":"single","required":true,"options":[{"value":"stesso_comune","label":"Nello stesso Comune"},{"value":"altro_comune","label":"Da un altro Comune"},{"value":"rimpatrio_aire","label":"Rimpatrio AIRE"},{"value":"altro","label":"Altro caso"}],"blockedValues":["altro"]},{"id":"altri_maggiorenni","title":"Sono coinvolti altri componenti maggiorenni?","type":"boolean","required":true}],"steps":[{"id":"verifica_percorso","title":"Verifica che il tuo caso sia gestibile su ANPR","description":"Se hai scelto un altro caso, rivolgiti al Comune. La guida ANPR limita le dichiarazioni gestite online.","kind":"task","required":true},{"id":"dati_abitazione","title":"Prepara indirizzo e titolo di occupazione","description":"La dichiarazione ANPR richiede i dati della nuova abitazione e il titolo che ne consente l’occupazione.","kind":"document","required":true},{"id":"convalida_maggiorenni","title":"Avvisa gli altri maggiorenni","description":"I componenti maggiorenni coinvolti devono convalidare nel portale ANPR con la propria identità digitale.","kind":"task","required":true,"when":{"questionId":"altri_maggiorenni","equals":true}},{"id":"portale_anpr","title":"Procedi sul portale ANPR","description":"Accedi al servizio ufficiale. La presentazione avviene sul portale, non su Veredoc.","kind":"portal","required":false,"url":"https://www.anagrafenazionale.interno.it/"}]}'::jsonb, 'DRAFT'),
('pv_certificati_1', 'pd_certificati', 1, '{"questions":[{"id":"destinatario","title":"Per chi richiedi il certificato?","type":"single","required":true,"options":[{"value":"me","label":"Per me"},{"value":"familiare","label":"Per un componente della famiglia anagrafica"},{"value":"terzo","label":"Per un terzo o come tutore"}],"blockedValues":["terzo"]},{"id":"certificato_storico","title":"Ti serve un certificato storico?","type":"boolean","required":true,"blockedValues":[true]}],"steps":[{"id":"verifica_ambito","title":"Verifica che la richiesta sia disponibile online","description":"Per terzi, tutori e certificati storici la guida indica di rivolgersi al Comune.","kind":"task","required":true},{"id":"scelta_certificato","title":"Individua il certificato da richiedere","description":"L’elenco disponibile dipende dai dati ANPR e può essere limitato dal Comune.","kind":"task","required":true},{"id":"portale_certificati","title":"Richiedi il certificato su ANPR","description":"Controlla l’anteprima e completa la richiesta sul portale ufficiale.","kind":"portal","required":false,"url":"https://www.anagrafenazionale.interno.it/"}]}'::jsonb, 'DRAFT'),
('pv_isee_1', 'pd_isee', 1, '{"questions":[{"id":"isee_specifico","title":"Ti serve un ISEE per una prestazione specifica?","type":"boolean","required":true},{"id":"precompilata","title":"Vuoi usare la DSU precompilata?","type":"boolean","required":true}],"steps":[{"id":"nucleo","title":"Raccogli i dati del nucleo familiare","description":"Il nucleo da dichiarare è quello alla data di presentazione della DSU.","kind":"document","required":true},{"id":"redditi","title":"Prepara i dati reddituali","description":"I redditi si riferiscono al secondo anno solare precedente la presentazione.","kind":"document","required":true},{"id":"patrimonio","title":"Prepara i dati patrimoniali","description":"Il patrimonio è quello posseduto al 31 dicembre del secondo anno precedente.","kind":"document","required":true},{"id":"autorizzazioni","title":"Organizza le autorizzazioni dei maggiorenni","description":"Per la precompilazione i maggiorenni autorizzano l’accesso ai dati con la propria identità digitale, oppure sono necessari gli elementi di riscontro.","kind":"task","required":true,"when":{"questionId":"precompilata","equals":true}},{"id":"portale_inps","title":"Compila la DSU su INPS","description":"Veredoc prepara i dati. La DSU ufficiale va compilata e inviata sul servizio INPS.","kind":"portal","required":false,"url":"https://www.inps.it/it/it/dettaglio-scheda.it.schede-servizio-strumento.schede-servizi.Portale-unico-ISEE.html"}]}'::jsonb, 'DRAFT')
